struct MaxFlowImplementation{
	int head[MAX_SIZE], v[MAX_EDGES], nxt[MAX_EDGES], capacity[MAX_EDGES], flow[MAX_EDGES], edgeCount;
	int dist[MAX_SIZE], current[MAX_SIZE];
	int s, t;
	void init(){
		memset(head, -1, sizeof head); edgeCount=0;
	}
	void addEdge(int u, int v, int c){
		v[edgeCount]=v; nxt[edgeCount]=head[u]; capacity[edgeCount]=c; flow[edgeCount]=0; head[u]=edgeCount++;
		v[edgeCount]=u; nxt[edgeCount]=head[v]; capacity[edgeCount]=0; flow[edgeCount]=0; head[v]=edgeCount++;
	}
	bool buildLevelGraph(){
		memset(dist, -1, sizeof dist);
		dist[s]=0;
		queue<int> q;
		q.push(s);
		while(!q.empty()){
			int u=q.front(); q.pop();
			for(int i=head[u]; ~i; i=nxt[i]){
				int v=v[i];
				if(dist[v]==-1 && capacity[i]>flow[i]){
					dist[v]=dist[u]+1;
					q.push(v);
				}
			}
		}
		return dist[t]!=-1;
	}
	int sendFlow(int u, int flowIn){
		if(u==t || flowIn==0) return flowIn;
		int totalFlow=0, pushed;
		for(int &i=current[u]; ~i; i=nxt[i]){
			int v=v[i];
			if(dist[v]==dist[u]+1 && (pushed=sendFlow(v, min(flowIn, capacity[i]-flow[i])))>0){
				flow[i]+=pushed;
				flow[i^1]-=pushed;
				flowIn-=pushed;
				totalFlow+=pushed;
				if(flowIn==0) break;
			}
		}
		return totalFlow;
	}
	int maxFlow(int s, int t){
		s=s; t=t;
		int total=0;
		while(buildLevelGraph()){
			memcpy(current, head, sizeof head);
			total+=sendFlow(s, MAX_FLOW_CAP);
		}
		return total;
	}
}maxFlowSolver;
